import { toUploadAttachmentDto } from "./attachments.js";
const toUploadStepDto = (step) => step.type === "attachment"
    ? { type: "attachment", attachment: toUploadAttachmentDto(step.link) }
    : {
        type: "body",
        body: step.name,
        status: step.status,
        start: step.start,
        stop: step.stop,
        duration: step.duration,
        message: typeof step.message === "string" ? step.message : undefined,
        trace: typeof step.trace === "string" ? step.trace : undefined,
        parameters: step.parameters,
        steps: step.steps?.map(toUploadStepDto),
    };
export const toUploadFixtureResultDto = (fxt) => ({
    type: fxt.type,
    uuid: fxt.id,
    name: fxt.name,
    start: fxt.start,
    stop: fxt.stop,
    duration: fxt.duration,
    status: fxt.status,
    message: fxt.error?.message,
    trace: fxt.error?.trace,
    steps: fxt.steps?.map(toUploadStepDto),
});
export const toUploadFixturesResultsDto = (fixtures) => ({
    fixtures: fixtures.map(toUploadFixtureResultDto),
});
